            const head = line.match(/^##\s*v?(\d+(?:\.\d+)*)\b/);
            if (head) { ver = head[1]; continue; }
            const item = ver && line.match(/^\s*[-*]\s+(.+?)\s*$/);
            if (!item) continue;
            if (verCmp(ver, from) > 0 && verCmp(ver, to) <= 0 && !out.some(n => n.ver === ver)) out.push({ ver, text: item[1] });
