                                    const bad = /[^\x00-\x7f]/.test(ev.target.value);
                                    if (hint) hint.style.display = bad ? '' : 'none';
                                    if (bad) { ev.target.value = e.key ?? ''; return; }
                                    const k = charKey(ev.target.value);
