            if (a >= 0 && b > a) try { j = JSON.parse(out.slice(a, b + 1)); } catch {}
            const got = j?.faces && typeof j.faces === 'object' ? j.faces : null;
            if (!got) throw new Error('얼굴 매칭 답을 읽지 못했습니다.');
            v.bot.faceAi = { sig, map: faceMap(got, names, pool) };
