        const pct = n ? Math.max(2, Math.min(95, Math.round(100 * (Math.min(i, n) + fill) / n))) : 2;
        const text = !n ? '본편 대사를 찾는 중입니다' : i < n ? `본편 대사를 모으는 중입니다 · ${i + 1} / ${n}` : '모은 대사를 적는 중입니다';
