        talkPersonaAt.set(v.chaId, Date.now());
        personaOf().then(p => (!p.sig || v.bot.voices[canonName(v.bot, p.name)]?.persona === p.sig) ? false : ensurePersona(v.chaId, v.bot, p, castMode()))
